-- Least-privilege role for the Audli 2.0 lesson generator. Run once as the database owner AFTER migration 012.
-- Create the role yourself first (a LOGIN role with its own password, shared with nothing else): CREATE ROLE audli_listening_generator LOGIN PASSWORD '...';
BEGIN;
GRANT USAGE ON SCHEMA public TO audli_listening_generator;
GRANT SELECT ON listening_lessons, listening_lesson_versions, listening_audio_variants, listening_exercises, listening_exercise_keys, listening_exercise_rubrics, listening_lesson_owners, listening_generation_requests, listening_generation_limits, listening_jobs, listening_ai_limits TO audli_listening_generator;
GRANT INSERT ON listening_lessons, listening_lesson_versions, listening_audio_variants, listening_exercises, listening_exercise_keys, listening_exercise_rubrics, listening_lesson_owners, listening_generation_limits, listening_ai_limits TO audli_listening_generator;
GRANT UPDATE ON listening_lesson_versions, listening_generation_requests, listening_generation_limits, listening_jobs TO audli_listening_generator;
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_lessons;
CREATE POLICY audli_listening_generator_select ON listening_lessons FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_lesson_versions;
CREATE POLICY audli_listening_generator_select ON listening_lesson_versions FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_audio_variants;
CREATE POLICY audli_listening_generator_select ON listening_audio_variants FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_exercises;
CREATE POLICY audli_listening_generator_select ON listening_exercises FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_exercise_keys;
CREATE POLICY audli_listening_generator_select ON listening_exercise_keys FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_exercise_rubrics;
CREATE POLICY audli_listening_generator_select ON listening_exercise_rubrics FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_lesson_owners;
CREATE POLICY audli_listening_generator_select ON listening_lesson_owners FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_generation_requests;
CREATE POLICY audli_listening_generator_select ON listening_generation_requests FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_generation_limits;
CREATE POLICY audli_listening_generator_select ON listening_generation_limits FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_jobs;
CREATE POLICY audli_listening_generator_select ON listening_jobs FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_select ON listening_ai_limits;
CREATE POLICY audli_listening_generator_select ON listening_ai_limits FOR SELECT TO audli_listening_generator USING (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_lessons;
CREATE POLICY audli_listening_generator_insert ON listening_lessons FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_lesson_versions;
CREATE POLICY audli_listening_generator_insert ON listening_lesson_versions FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_audio_variants;
CREATE POLICY audli_listening_generator_insert ON listening_audio_variants FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_exercises;
CREATE POLICY audli_listening_generator_insert ON listening_exercises FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_exercise_keys;
CREATE POLICY audli_listening_generator_insert ON listening_exercise_keys FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_exercise_rubrics;
CREATE POLICY audli_listening_generator_insert ON listening_exercise_rubrics FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_lesson_owners;
CREATE POLICY audli_listening_generator_insert ON listening_lesson_owners FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_generation_limits;
CREATE POLICY audli_listening_generator_insert ON listening_generation_limits FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_insert ON listening_ai_limits;
CREATE POLICY audli_listening_generator_insert ON listening_ai_limits FOR INSERT TO audli_listening_generator WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_update ON listening_lesson_versions;
CREATE POLICY audli_listening_generator_update ON listening_lesson_versions FOR UPDATE TO audli_listening_generator USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_update ON listening_generation_requests;
CREATE POLICY audli_listening_generator_update ON listening_generation_requests FOR UPDATE TO audli_listening_generator USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_update ON listening_generation_limits;
CREATE POLICY audli_listening_generator_update ON listening_generation_limits FOR UPDATE TO audli_listening_generator USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_generator_update ON listening_jobs;
CREATE POLICY audli_listening_generator_update ON listening_jobs FOR UPDATE TO audli_listening_generator USING (true) WITH CHECK (true);
COMMIT;
